/* Header */

header {
  display: flow-root;
  position: relative;
  font-weight: 300;
  font-size: 1.8rem;
  line-height: 1em;
  margin-block: 0;
  z-index: 3;

  & .sub-view-title {
    font-size: 1.7rem;
    font-weight: 400;
    margin-block: var(--hub-header-margin-block-start) 0;
    color: var(--color-text-base);
  }

  & .sub-view-sub-header {
    font-size: 1rem;
    font-weight: 700;
    margin-block: var(--hub-subheader-margin-block-start) 0;
    color: var(--color-primary-pressed);
  }
}

.branding-header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: center;
  gap: 11px;

  h1 {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    margin-block: 0 2px;
    align-self: center;
  }
}

#headerButtonsContainer {
  display: flex;
  align-items: center;
  gap: 3px;
  position: absolute;
  inset-inline-end: -5px;
  inset-block-start: -25px;
  z-index: 3;
